/**
 * Fake Archify CLI for MyGRACE tests (fixtures only — never shipped).
 *
 * Generates a POSIX `archify` wrapper that forwards to a small Node-compatible
 * ESM script, so the real ADR-9 child-process path is exercised without
 * installing Archify. Modes:
 *   ok           — validate ok, deliver writes HTML + `.delivery.json`
 *   invalid      — validate/deliver answer `{ok:false}` (schema rejection path)
 *   deliver-fail — validate ok, deliver answers `{ok:false}` (delivery failure path)
 *   crash        — prints a non-JSON error and exits 2 (invalid-output path)
 *
 * The wrapper is a `#!/bin/sh` script: tests that execute it are POSIX-only.
 * `mjs` is exposed so a separate test can exercise the Node-script runner when
 * `node` is available on PATH.
 */
import { chmodSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

export type FakeArchifyMode = "ok" | "invalid" | "deliver-fail" | "crash";

export interface FakeArchify {
  /** Absolute path to the executable wrapper (use as integrations.archify.bin). */
  bin: string;
  /** Absolute path to the ESM script (for Node-runner tests). */
  mjs: string;
  mode: FakeArchifyMode;
  cleanup(): void;
}

const SERVER = String.raw`import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";

const argv = process.argv.slice(2);
const command = argv[0];
const mode = __MODE__;
const emit = (payload, code = 0) => {
  console.log(JSON.stringify(payload));
  process.exit(code);
};

if (mode === "crash") {
  console.error("fake archify internal error");
  process.exit(2);
}
if (command !== "validate" && command !== "deliver") {
  emit({ schemaVersion: 1, ok: false, error: "unsupported command: " + String(command) }, 2);
}
const input = argv[2];
let parsed;
try {
  parsed = JSON.parse(readFileSync(input, "utf8"));
} catch {
  emit({ schemaVersion: 1, ok: false, error: "invalid input JSON" }, 1);
}
if (mode === "invalid") {
  emit({ schemaVersion: 1, ok: false, command, error: "fake schema rejection", diagnostics: [] }, 1);
}
if (command === "validate") {
  emit({ schemaVersion: 1, ok: true, command: "validate", type: "architecture", input });
}
const output = argv[3];
if (!output) emit({ schemaVersion: 1, ok: false, command, error: "missing output path" }, 2);
if (mode === "deliver-fail") {
  emit({ schemaVersion: 1, ok: false, command, error: "fake delivery failure" }, 1);
}
mkdirSync(dirname(output), { recursive: true });
writeFileSync(output, "<!doctype html><title>fake archify</title>\n");
writeFileSync(
  output.replace(/[.]html$/i, ".delivery.json"),
  JSON.stringify({ receiptId: "fake-receipt", output, htmlSha256: "deadbeef", bytes: 42 })
);
emit({
  schemaVersion: 1,
  ok: true,
  command: "deliver",
  type: "architecture",
  input,
  output,
  bytes: 42,
});
`;

function shellQuote(value: string): string {
  return `'${value.replace(/'/g, `'\\''`)}'`;
}

export function makeFakeArchify(options: { mode?: FakeArchifyMode } = {}): FakeArchify {
  const mode = options.mode ?? "ok";
  const dir = mkdtempSync(join(tmpdir(), "mygrace-fake-archify-"));
  const mjs = join(dir, "fake-archify.mjs");
  writeFileSync(mjs, SERVER.replace("__MODE__", JSON.stringify(mode)), "utf-8");
  const bin = join(dir, "archify");
  writeFileSync(
    bin,
    [
      "#!/bin/sh",
      "# Generated by test/fixtures/archify/fake-archify.ts — fake Archify for tests.",
      `exec ${shellQuote(process.execPath)} ${shellQuote(mjs)} "$@"`,
      "",
    ].join("\n"),
    { encoding: "utf-8", mode: 0o755 }
  );
  chmodSync(bin, 0o755);
  return {
    bin,
    mjs,
    mode,
    cleanup: () => rmSync(dir, { recursive: true, force: true }),
  };
}
